pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address newOwner, uint48 seed) public {
        // Restrict newOwner to non-zero addresses: zero is not a valid transfer target
        // and the bug explicitly accepts only zero, so the interesting difference is for non-zero.
        vm.assume(newOwner != address(0));
        // Use seed to pick the caller distinct from the current owner to avoid confusion
        address caller = address(uint160(uint256(keccak256(abi.encode(seed)))));
        vm.assume(caller != c.owner());
        // Ensure caller is not the zero address either
        vm.assume(caller != address(0));

        // Prerequisite: the current owner must call transferOwnership.
        // We prank as the current owner.
        vm.prank(c.owner());
        bool success = true;
        try c.transferOwnership(newOwner) {
        } catch {
            success = false;
        }
        // The property: a non-zero newOwner transfer must succeed and change the owner.
        assertTrue(success && c.owner() == newOwner);
    }
}

